    def forward(self, x: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        """x: [B, F, T, N], mask: [B, 1, T, N] (broadcast). Returns reconstruction."""
        x_masked = x.clone()
        x_masked[mask.expand_as(x)] = self.mask_token.unsqueeze(0).expand_as(
